    <section className={`section ${slug === 'modular-fixtures' ? 'inner-soft' : ''}`}><div className="container"><SectionHeading eyebrow={slug === 'modular-fixtures' ? 'FEATURES AND ADVANTAGES' : 'A PRACTICAL APPROACH'} title={headings[category.slug]}/><div className="scope-grid">{considerations[category.slug].map((item,index) => <article key={item.title}><span className="scope-number">0{index+1}</span><h3>{item.title}</h3><p>{item.description}</p></article>)}</div></div></section>
