    {slug === 'accessories' && <section className="section inner-soft"><div className="container"><SectionHeading eyebrow="PRODUCT RANGE" title="Probe heads, probes, styli and CMM spares." description="Tell us your CMM make, probe head and part numbers — we will confirm compatibility and availability."/><ListColumns groups={accessoryGroups}/></div></section>}
    {(matching.length > 0 || slug === 'used-cmm') && <section className={`section ${slug === 'accessories' ? '' : 'inner-soft'}`}><div className="container">{matching.length ? <><SectionHeading eyebrow="EQUIPMENT LISTINGS" title="Current equipment."/><div className="equipment-grid">{matching.map(product => <ProductCard product={product} key={product.id}/>)}</div></> : <Availability service={category.service}/>}</div></section>}
    {slug === 'used-cmm' && <section className="section"><div className="container"><SectionHeading eyebrow="USED CMM BY BRAND" title="Buying or selling a used CMM?" description="We help buyers and sellers of used Mitutoyo, Zeiss, Hexagon, Brown & Sharpe, DEA, Leitz, LK, Wenzel, Coord3, Tesa, Accurate, GMT and Sheffield CMMs."/><BrandChips label="USED CMM"/><div className="inner-split" style={{marginTop: 60}}><div><p className="eyebrow">BEFORE YOU BUY</p><h2>Ask the questions that matter.</h2></div><div className="prose"><p>Working range is only part of the decision. Consider the machine’s configuration, its documentation, the installation environment and the support your team will need.</p><Link to="/resources/choosing-a-used-cmm" className="text-link">Read the used CMM buying guide <ArrowRight size={18}/></Link></div></div></div></section>}
