export function Resources() {
  const [active,setActive] = useState('All');
  const categories=['All',...resources.map(resource=>resource.category)];
  const shown=active==='All'?resources:resources.filter(resource=>resource.category===active);
  return <><PageHero current="Resources" eyebrow="PRACTICAL METROLOGY NOTES" title="Useful knowledge. Better conversations." description="Clear starting points for equipment decisions, inspection enquiries and the care of your coordinate measuring machine."/>
    <section className="section"><div className="container"><div className="resource-filter" role="group" aria-label="Filter resources">{categories.map(category=><button key={category} className={active===category?'active':''} onClick={()=>setActive(category)} aria-pressed={active===category}>{category==='All'?'All resources':category.toLowerCase()}</button>)}</div><div className="resource-grid">{shown.map((resource,index)=><Link to={`/resources/${resource.slug}`} className="resource-card" key={resource.slug}><div className={`resource-art resource-art-${resources.indexOf(resource)+1}`}><div aria-hidden="true">{resources.indexOf(resource)===0?<Settings2/>:resources.indexOf(resource)===1?<FileCheck2/>:<Box/>}</div><span>HAVISS / TECHNICAL NOTES</span><b>{String(resources.indexOf(resource)+1).padStart(2,'0')}</b></div><div className="resource-card-body"><div className="resource-meta"><span>{resource.category}</span><span>{resource.readTime}</span></div><h2>{resource.title}</h2><p>{resource.summary}</p><span className="text-link">Read the guide <ArrowUpRight size={17}/></span></div></Link>)}</div></div></section><ContactBanner title="Have a question specific to your machine?" description="General guidance is a starting point. Share your configuration and requirement for a technical discussion."/></>;
}

